$canWrite=$project!==null&&isset($writable[$project]);
?>
<p class="lede">Счета и фактические расчёты. Остатки рассчитываются только по проведённым платежам и возвратам, отдельно по валютам.</p>
<form method="get" class="filters"><input type="hidden" name="p" value="invoices"><label>Проект<select name="project"><option value="">Все доступные проекты</option><?php selectOptions($projects,$project) ?></select></label><button class="secondary">Выбрать</button></form>
