<?php if($canWrite): ?><details class="editor"><summary>Новый счёт</summary><?php if(!$entities||!$clients): ?><p>Добавьте юридическое лицо и контрагента. <a href="<?= h(url('clients')) ?>">Справочник клиентов</a> доступен владельцу.</p><?php else: ?><form method="post" class="formgrid"><?php formFields('invoice.create') ?><input type="hidden" name="project_id" value="<?= h($project) ?>"><label>Исполнитель<select required name="entity_id"><?php selectOptions(array_column($entities,'name','id')) ?></select></label><label>Контрагент<select required name="counterparty_id"><?php selectOptions(array_column($clients,'name','id')) ?></select></label><label>Валюта<select name="currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES)) ?></select></label><label>Оплатить до<input type="date" name="due_on" required min="<?= gmdate('Y-m-d') ?>" value="<?= gmdate('Y-m-d',time()+14*86400) ?>"></label><label>Условия оплаты<input name="terms" required maxlength="1000" placeholder="Оплата банковским переводом"></label><div class="formend"><button class="primary">Создать черновик</button></div></form><?php endif ?></details><?php endif ?>
<?php if($invoice): $taxDocument=$taxDocument??null;$taxProfile=$taxProfile??null;$i=$invoice;$hidden=function(string $act)use($i){formFields($act);echo '<input type="hidden" name="project_id" value="',h($i['project_id']),'"><input type="hidden" name="id" value="',h($i['id']),'"><input type="hidden" name="version" value="',h($i['version']),'">';}; ?>
<section class="panel"><div class="panelhead"><h2>Счёт <?= h(invoiceNumber($i)) ?> · <?= h($states[$i['state']]) ?></h2><a href="<?= h(url('invoices',['project'=>$project])) ?>">К списку</a></div>
<p>Проект: <?= h($projects[$project]) ?> · Валюта <?= h($i['currency']) ?> · Оплатить до <?= h(displayDate($i['due_on'])) ?> · <?= h($i['terms']) ?></p>
<?php if($i['state']!=='draft'): $seller=json_decode($i['issuer_snapshot'],true,512,JSON_THROW_ON_ERROR);$buyer=json_decode($i['client_snapshot'],true,512,JSON_THROW_ON_ERROR); ?><p>Дата выставления: <?= h(displayDate($i['issued_on'])) ?></p><p><b>Исполнитель:</b> <?= h($seller['name']) ?> · <?= h($seller['registration']) ?> · <?= h($seller['address']) ?><br><?= h($seller['bank_details']) ?></p><p><b>Заказчик:</b> <?= h($buyer['name']) ?> · <?= h($buyer['registration']) ?></p><?php else: ?><p>Юрлицо #<?= h($i['entity_id']) ?> · Контрагент #<?= h($i['counterparty_id']) ?>. Реквизиты фиксируются при выставлении.</p><?php endif ?>
<div class="tablewrap"><table><thead><tr><th>Позиция</th><th>Количество</th><th>Цена</th><th>Сумма</th><?php if($canWrite&&$i['state']==='draft'): ?><th></th><?php endif ?></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= h($l['description']) ?></td><td><?= h($l['quantity']) ?></td><td><?= h(money((int)$l['unit_minor'])) ?></td><td><?= h(money(invoiceLineAmount((int)$l['quantity'],(int)$l['unit_minor']))) ?></td><?php if($canWrite&&$i['state']==='draft'): ?><td><form method="post"><?php $hidden('invoice.remove') ?><input type="hidden" name="line_id" value="<?= h($l['id']) ?>"><button class="secondary compact">Удалить</button></form></td><?php endif ?></tr><?php endforeach ?></tbody></table></div>
<?php if($taxProfile): ?><p>UK VAT: проверьте, что все цены черновика указаны без налога. VAT 20% начисляется при выставлении.</p><?php if((int)$i['total_minor']>0): try{$preview=ukVatTotals((int)$i['total_minor']); ?><p>VAT <?= h(money($preview['vat'])) ?> GBP · С VAT <?= h(money($preview['gross'])) ?> GBP</p><?php }catch(Problem $e){ ?><p><?= h($e->getMessage()) ?></p><?php } endif; endif ?>
<?php if($taxDocument): ?><p>Без VAT <?= h(money((int)$taxDocument['net_minor'])) ?> GBP · VAT 20% <?= h(money((int)$taxDocument['vat_minor'])) ?> GBP · <a href="<?= h(url('tax.print',['project'=>$project,'id'=>$i['id']])) ?>">Печатный VAT invoice</a><?php if($taxDocument['credit_on']): ?> · <a href="<?= h(url('tax.print',['project'=>$project,'id'=>$i['id'],'credit'=>1])) ?>">Печатная credit note</a><?php endif ?></p><?php endif ?>
<p><b>Итого: <?= h(money((int)$i['total_minor']).' '.$i['currency']) ?></b></p>
<?php if($canWrite&&$i['state']==='draft'): ?><form method="post" class="formgrid"><?php $hidden('invoice.line') ?><label>Позиция<input name="description" maxlength="500" required></label><label>Количество<input type="number" name="quantity" min="1" max="100000" value="1" required></label><label>Цена за единицу<input name="unit" inputmode="decimal" required></label><div class="formend"><button class="secondary">Добавить позицию</button></div></form>
<form method="post" class="formgrid"><?php $hidden('invoice.terms') ?><label>Срок оплаты<input type="date" name="due_on" value="<?= h($i['due_on']) ?>" required></label><label>Условия<input name="terms" maxlength="1000" required value="<?= h($i['terms']) ?>"></label><div class="formend"><button class="secondary">Сохранить условия</button></div></form>
<form method="post"><?php $hidden('invoice.issue') ?><?php if($taxProfile): ?><input type="hidden" name="uk_profile_version" value="<?= h($taxProfile['version']) ?>"><label>Адрес покупателя в UK<input name="buyer_address" required maxlength="500"></label><label>Дата поставки и tax point<input type="date" name="tax_point" value="<?= h(ukToday()) ?>" required></label><label><input type="checkbox" name="uk_confirm" value="1" required> Внутренние стандартно облагаемые B2B-услуги, поставка сегодня, без авансов, скидок и специальных режимов</label><?php endif ?><button class="primary">Выставить счёт (зафиксировать)</button></form><?php endif ?>
<?php if($i['state']==='issued'): ?><div class="currencies"><?php foreach(['received'=>'Поступило','refunded'=>'Возвращено','outstanding'=>'Остаток долга','pending_receipt'=>'Ожидает оплаты','pending_refund'=>'Ожидает возврата'] as $k=>$label): ?><div class="currency"><span><?= h($label) ?></span><strong><?= h(money($balance[$k])) ?></strong></div><?php endforeach ?></div>
<?php if($canWrite): ?><details class="editor"><summary>Зарегистрировать поступление</summary><form method="post" class="formgrid"><?php $hidden('invoice.payment') ?><input type="hidden" name="kind" value="receipt"><label>Сумма<input name="amount" required inputmode="decimal"></label><label>Дата<input type="date" name="booked_on" required value="<?= h($taxDocument?ukToday():gmdate('Y-m-d')) ?>" min="<?= h($i['issued_on']) ?>" max="<?= h($taxDocument?ukToday():gmdate('Y-m-d')) ?>"></label><label>Уникальный идентификатор платежа<input name="reference" maxlength="180" required></label><div class="formend"><button class="primary">Зарегистрировать оплату</button></div></form></details>
<?php $sources=[];foreach($movements as $m)if($m['kind']==='receipt'&&$m['status']==='posted')$sources[$m['id']]=$m['reference'].' · '.money((int)$m['amount_minor']); if($sources): ?><details class="editor"><summary>Зарегистрировать возврат</summary><form method="post" class="formgrid"><?php $hidden('invoice.payment') ?><input type="hidden" name="kind" value="refund"><label>Исходное поступление<select name="original_id"><?php selectOptions($sources) ?></select></label><label>Сумма<input name="amount" required inputmode="decimal"></label><label>Дата<input type="date" name="booked_on" required value="<?= h($taxDocument?ukToday():gmdate('Y-m-d')) ?>" max="<?= h($taxDocument?ukToday():gmdate('Y-m-d')) ?>"></label><label>Идентификатор возврата<input name="reference" maxlength="180" required></label><div class="formend"><button class="secondary">Зарегистрировать возврат</button></div></form></details><?php endif ?>
<?php if($taxDocument && $balance['received']===$balance['refunded']&&!$balance['pending_receipt']&&!$balance['pending_refund']): ?><form method="post" class="formgrid"><?php $hidden('invoice.credit') ?><label>Основание полной кредит-ноты (отмена поставки / согласованное уменьшение цены до нуля)<input name="reason" required maxlength="500"></label><button class="secondary">Выпустить credit note</button></form><?php elseif(!$taxDocument&&!$balance['received']&&!$balance['pending_receipt']&&!$balance['pending_refund']): ?><form method="post"><?php $hidden('invoice.void') ?><button class="secondary">Аннулировать неоплаченный счёт</button></form><?php endif; endif; endif ?>
<h3>История расчётов</h3><p><a href="<?= h(url('payments',['project'=>$project])) ?>">Согласование платежей</a></p><div class="tablewrap"><table><thead><tr><th>Дата / ссылка</th><th>Операция</th><th>Сумма</th><th>Статус</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?= h($m['booked_on']) ?> · <?= h($m['reference']) ?><small>Заявка #<?= h($m['request_id']) ?><?php if($m['original_id']): ?> · возврат движения #<?= h($m['original_id']) ?><?php endif ?></small></td><td><?= $m['kind']==='receipt'?'Оплата':'Возврат' ?> #<?= h($m['id']) ?></td><td><?= h(money((int)$m['amount_minor']).' '.$i['currency']) ?></td><td><?= h($movementStates[$m['status']]) ?><?php if($m['cash_entry_id']): ?><small>Касса #<?= h($m['cash_entry_id']) ?></small><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php endif ?>
<section class="panel"><div class="panelhead"><h2>Реестр счетов</h2></div><div class="tablewrap"><table><thead><tr><th>Номер / проект</th><th>Срок</th><th>Состояние</th><th>Сумма</th><th>Долг</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="<?= h(url('invoices',['project'=>$r['project_id'],'id'=>$r['id']])) ?>"><?= h(invoiceNumber($r)) ?> #<?= h($r['id']) ?></a><small><?= h($r['project_title']) ?></small></td><td><?= h(displayDate($r['due_on'])) ?></td><td><?= h($states[$r['state']]) ?><?php if($r['state']==='issued'&&(int)$r['remaining']>0&&$r['due_on']<gmdate('Y-m-d')): ?><small>Просрочен</small><?php endif ?></td><td><?= h(money((int)$r['total_minor']).' '.$r['currency']) ?></td><td><?= $r['state']==='issued'?h(money((int)$r['remaining']).' '.$r['currency']):'—' ?></td></tr><?php endforeach ?></tbody></table></div><?php if($nextBefore): ?><a href="<?= h(url('invoices',array_filter(['project'=>$project,'before'=>$nextBefore]))) ?>">Следующая страница</a><?php endif ?></section>
